pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 ts, address sender, uint256 amount) public {
        vm.assume(amount == 10 ether);
        vm.assume(ts > 0);

        vm.deal(sender, 10 ether);

        vm.warp(ts);

        uint256 bn = block.number;

        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok);

        bool div15 = (bn % 15 == 0);
        if (div15) {
            assertTrue(address(c).balance == 0);
        } else {
            assertTrue(address(c).balance == 10 ether);
        }
    }
}
